PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS audit_raw_events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_time TEXT NOT NULL, event_type TEXT NOT NULL, raw_line TEXT NOT NULL, raw_hash TEXT NOT NULL, node_id TEXT NOT NULL, ingested_at TEXT NOT NULL, UNIQUE(raw_hash,event_time,node_id));
CREATE TABLE IF NOT EXISTS audit_access_events (id INTEGER PRIMARY KEY AUTOINCREMENT, raw_event_id INTEGER NOT NULL UNIQUE, event_time TEXT NOT NULL, user_email TEXT NOT NULL, src TEXT NOT NULL, dest_raw TEXT NOT NULL, dest_host TEXT NOT NULL, dest_port INTEGER, status TEXT NOT NULL, detour TEXT NOT NULL, reason TEXT NOT NULL, is_domain INTEGER NOT NULL CHECK(is_domain IN (0,1)), confidence TEXT NOT NULL, FOREIGN KEY(raw_event_id) REFERENCES audit_raw_events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_dns_events (id INTEGER PRIMARY KEY AUTOINCREMENT, raw_event_id INTEGER NOT NULL UNIQUE, event_time TEXT NOT NULL, dns_server TEXT NOT NULL, domain TEXT NOT NULL, ips_json TEXT NOT NULL, dns_status TEXT NOT NULL, elapsed_ms INTEGER, error_text TEXT NOT NULL, FOREIGN KEY(raw_event_id) REFERENCES audit_raw_events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS collector_state (id INTEGER PRIMARY KEY AUTOINCREMENT, file_path TEXT NOT NULL UNIQUE, inode INTEGER, last_offset INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_ip_geo_cache (ip TEXT PRIMARY KEY, country TEXT NOT NULL, region TEXT NOT NULL, city TEXT NOT NULL, isp TEXT NOT NULL, addr TEXT NOT NULL, status TEXT NOT NULL, source TEXT NOT NULL, raw_json TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_error_events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_time TEXT NOT NULL, level TEXT NOT NULL, session_id INTEGER, component TEXT NOT NULL, message TEXT NOT NULL, src TEXT NOT NULL, dest_raw TEXT NOT NULL, dest_host TEXT NOT NULL, dest_port INTEGER, category TEXT NOT NULL, signature_hash TEXT NOT NULL, is_noise INTEGER NOT NULL CHECK(is_noise IN (0,1)), raw_line TEXT NOT NULL, raw_hash TEXT NOT NULL, node_id TEXT NOT NULL, ingested_at TEXT NOT NULL, UNIQUE(raw_hash,event_time,node_id));
CREATE TABLE IF NOT EXISTS audit_job_state (state_key TEXT PRIMARY KEY, value_text TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_admin_users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT COLLATE NOCASE NOT NULL UNIQUE, password_hash TEXT NOT NULL, token_version INTEGER NOT NULL DEFAULT 0, is_enabled INTEGER NOT NULL DEFAULT 1, must_change_password INTEGER NOT NULL DEFAULT 0, last_login_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_runtime_config (config_key TEXT PRIMARY KEY, value_json TEXT NOT NULL, value_type TEXT NOT NULL, scope TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_runtime_config_history (id INTEGER PRIMARY KEY AUTOINCREMENT, config_key TEXT NOT NULL, old_value_json TEXT, new_value_json TEXT NOT NULL, changed_by TEXT NOT NULL, source_ip TEXT NOT NULL, changed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_auth_events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_type TEXT NOT NULL, username TEXT NOT NULL, source_ip TEXT NOT NULL, user_agent TEXT NOT NULL, event_time TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_raw_time ON audit_raw_events(event_time); CREATE INDEX IF NOT EXISTS idx_raw_type_time ON audit_raw_events(event_type,event_time);
CREATE INDEX IF NOT EXISTS idx_access_user_time ON audit_access_events(user_email,event_time); CREATE INDEX IF NOT EXISTS idx_access_dest_time ON audit_access_events(dest_host,event_time); CREATE INDEX IF NOT EXISTS idx_access_time ON audit_access_events(event_time); CREATE INDEX IF NOT EXISTS idx_access_status ON audit_access_events(event_time,status); CREATE INDEX IF NOT EXISTS idx_access_detour ON audit_access_events(event_time,detour);
CREATE INDEX IF NOT EXISTS idx_dns_domain_time ON audit_dns_events(domain,event_time); CREATE INDEX IF NOT EXISTS idx_dns_time ON audit_dns_events(event_time); CREATE INDEX IF NOT EXISTS idx_geo_updated ON audit_ip_geo_cache(updated_at);
CREATE INDEX IF NOT EXISTS idx_err_time ON audit_error_events(event_time); CREATE INDEX IF NOT EXISTS idx_err_level_time ON audit_error_events(level,event_time); CREATE INDEX IF NOT EXISTS idx_err_category_time ON audit_error_events(category,event_time); CREATE INDEX IF NOT EXISTS idx_err_noise_time ON audit_error_events(is_noise,event_time); CREATE INDEX IF NOT EXISTS idx_err_sig_time ON audit_error_events(signature_hash,event_time);
CREATE INDEX IF NOT EXISTS idx_admin_enabled ON audit_admin_users(is_enabled); CREATE INDEX IF NOT EXISTS idx_runtime_updated ON audit_runtime_config(updated_at); CREATE INDEX IF NOT EXISTS idx_history_time ON audit_runtime_config_history(changed_at); CREATE INDEX IF NOT EXISTS idx_history_key_time ON audit_runtime_config_history(config_key,changed_at); CREATE INDEX IF NOT EXISTS idx_auth_time ON audit_auth_events(event_time); CREATE INDEX IF NOT EXISTS idx_auth_user_time ON audit_auth_events(username,event_time); CREATE INDEX IF NOT EXISTS idx_auth_type_time ON audit_auth_events(event_type,event_time);
